import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { ContactRecordPage } from '../../pages/ContactRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectRecordTitle,
  expectSavePopover,
  expectToast,
  relatedListRecord,
  waitForSpinners,
} from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Duplicate contact warning shown when saving Contact with same Email on same Account', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-050 Duplicate contact warning shown when saving Contact with same Email on same Account',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-050',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const contactRecordPage = new ContactRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const duplicate = data.unique('duplicate', 'text', 80);
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Navigate to the Account record page and click New Contact', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): New Contact modal opens with Account Name pre-populated
        await accountRecordPage.open(data.id('Account'));
        await accountRecordPage.listInRelated(accountRecordPage.contactsRelatedList);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.accountId).toHaveValue(data.value('Account', 'Name'));
      });
      await test.step("2. Enter First Name 'Test', Last Name 'Duplicate', Email '<EMAIL_1>' (same as existing Contact on this Account), then click Save", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): A possible duplicate warning is displayed indicating a Contact with the same Email already exists on this Account; the Save button remains enabled
        await newContactDialog.firstName.fill('Test');
        await newContactDialog.lastName.fill(duplicate);
        await newContactDialog.email.fill(data.value('Contact', 'Email'));
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectSavePopover(
          page,
          'Similar Records Exist',
          'This record looks like an existing record. Make sure to check any potential duplicate records before saving.',
        ); // observed on qa-prod (om-run-p5-observe-8-5), accepted by Rakesh Sharma; closed afterwards
        await expect(newContactDialog.saveButton).toBeVisible();
      });
      await test.step('3. Click Save in the New Contact dialog again to save the duplicate Contact (the duplicate warning has no Save button of its own)', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC4): The Contact record is saved and its record, opened from the Account's Contacts related list, shows the entered Last Name 'Duplicate' and Email 'duplicate@test.com'
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectToast(page, duplicate); // 1. the success toast names the record
        await accountRecordPage.listInRelated(accountRecordPage.contactsRelatedList);
        await expect(relatedListRecord(accountRecordPage.contactsRelatedList, duplicate)).toBeVisible(); // 2. in the related list with that name
        await data.adopt('newContact', 'Contact', 'LastName', duplicate); // code-owned cleanup: tagged by its run-unique name
        await relatedListRecord(accountRecordPage.contactsRelatedList, duplicate).click(); // 3. opened from the related list
        await expectRecordTitle(page, duplicate);
        {
          // 4. SOQL by the run tag: exactly this record, with the values entered
          const saved = await data.tagged('Contact', { LastName: duplicate }, [
            'FirstName',
            'LastName',
            'Email',
            'Account.Name',
          ]);
          expect(saved).toHaveLength(1);
          expect(saved[0]).toMatchObject({
            FirstName: 'Test',
            LastName: duplicate,
            Email: data.value('Contact', 'Email'),
            'Account.Name': data.value('Account', 'Name'),
          });
        }
        await expect(await contactRecordPage.fieldInDetails(contactRecordPage.emailField)).toContainText(
          data.value('Contact', 'Email'),
        );
      });
      await test.step("4. Verify via SOQL that the duplicate Contact was saved on the Account with Email '<EMAIL_1>', and that the pre-existing Contact is still on that Account", async () => {
        // Expected (DECLARED_CONFIG; OC-005, DuplicateRule:Contact.Contact_Same_Email_Same_Account, BRD-CON-012#BR-10): SOQL query confirms the new Contact record exists on the Account with Email 'duplicate@test.com' alongside the pre-existing Contact
        await expect
          .poll(() => soqlValue(sf, 'Contact', data.id('Contact'), 'Email'))
          .toBe(data.value('Contact', 'Email'));
        await expect
          .poll(() => soqlValue(sf, 'Contact', data.id('newContact'), 'Account.Name'))
          .toBe(data.value('Account', 'Name'));
      });
    },
  );
});
